def second_largest(xs):
    """
    Returns the second largest unique value from the list xs, or None if there is no such value.
    """

    def dfs(x, stack):
        """Recursive helper function"""
        if x not in stack:
            stack.append(x)
            return dfs(next(x), stack)
        return stack[-2]

    if not xs:
        return None
    if len([x for x in xs if x == x]) == len(xs):
        return None
    else:
        return dfs(*sorted(set(xs)), [])
```

