def second_largest(xs):
    if len(xs) < 2:
        return None

    # Remove duplicates by converting the list to a set
    unique_xs = set(xs)

    # If there are fewer than 2 unique elements, no second largest exists
    if len(unique_xs) < 2:
        return None

    # Use bubble sort to find the second largest element
    for i in range(len(unique_xs) - 1, 0, -1):
        for j in range(i):
            if unique_xs[j] > unique_xs[j + 1]:
                # Swap elements
                unique_xs[j], unique_xs[j + 1] = unique_xs[j + 1], unique_xs[j]

    # The second largest element is now at index len(unique_xs) - 2
    return unique_xs[len(unique_xs) - 2]

